<style>
#item-modal .modal-dialog{max-width:1000px}#item-modal .modal-content{border-radius:5px}#item-modal .modal-header{padding:28px 32px;direction:rtl;border-bottom:1px solid #e9eaf1}#item-modal .modal-header h5{font-size:18px;font-weight:500;margin:0}#item-modal .modal-header .btn-close{margin:0 auto 0 0}#item-modal .modal-body{padding:0}
.si-editor{direction:rtl;color:#50535d;background:#fff}.si-editor .si-editor-body{padding:24px 32px 32px}.si-editor .nav-tabs{justify-content:flex-start;gap:16px;border-bottom:2px solid #eeeff8;margin-bottom:24px}.si-editor .nav-tabs .nav-link{border:0;background:transparent;padding:16px 8px;color:#81828e;border-radius:0;font-size:15px}.si-editor .nav-tabs .nav-link.active{color:#635fee;border-bottom:3px solid #635fee}.si-editor .nav-link i{margin-left:8px}.si-editor .si-section{color:#6266cc;border-bottom:1px dashed #edeef4;font-size:14px;font-weight:700;padding:4px 0 13px;margin:24px 0}.si-editor .si-line{display:grid;grid-template-columns:24% 56%;gap:24px;align-items:center;margin:20px 0}.si-editor .si-line>label{font-weight:600;font-size:14px;margin:0}.si-editor .form-control,.si-editor .form-select{min-height:48px;border:1px solid #e5e7f1;border-radius:4px;box-shadow:none;font-weight:400}.si-editor .form-control:focus,.si-editor .form-select:focus{border-color:#7068ff}.si-editor .si-help{font-size:12px;color:#9497a7;margin:7px 0 0;line-height:1.7}.si-editor .si-switch{display:flex;justify-content:flex-start}.si-editor .si-switch input{width:52px;height:28px;margin:0;cursor:pointer}.si-editor .si-extra{margin-top:32px;border-top:1px solid #eee;padding-top:12px}.si-editor .si-extra>summary{font-size:13px;color:#9295a5;cursor:pointer}.si-editor .si-actions{display:flex;direction:ltr;gap:8px;padding:24px 32px;border-top:1px solid #eaebf0;position:sticky;bottom:0;background:white;z-index:2}.si-editor .si-actions .btn{padding:10px 22px;border-radius:4px}.si-editor .si-actions .btn-primary{background:#6260dc;border-color:#6260dc}.si-editor .si-time-grid{display:grid;grid-template-columns:repeat(8,minmax(0,1fr));gap:4px;direction:rtl}.si-editor .si-time-grid>div{min-width:0!important;width:auto!important;padding:0}.si-editor .si-time-grid button{font-size:11px;padding:6px 2px;border-radius:4px}.si-editor .si-legend{display:flex;gap:14px;justify-content:flex-start;flex-