.si-editor .si-switch.form-switch{padding:0;margin:0;min-height:0}.si-editor .si-switch .form-check-input{float:none;margin:0!important;flex:0 0 auto}.si-editor .si-switch .form-check-input:checked{background-color:#635fee;border-color:#635fee}
.si-editor .si-extra{border:1px solid #e9eaf1;border-radius:8px;padding:0;margin-top:32px}.si-editor .si-extra>summary{list-style:none;display:flex;align-items:center;gap:8px;padding:14px 18px;font-size:14px;font-weight:600;color:#50535d;background:#f8f8fb;border-radius:8px}.si-editor .si-extra>summary::-webkit-details-marker{display:none}.si-editor .si-extra>summary>i:first-child{color:#635fee}.si-editor .si-extra .si-extra-caret{margin-inline-start:auto;font-size:11px;color:#9295a5;transition:transform .2s}.si-editor .si-extra[open]>summary{border-bottom:1px solid #e9eaf1;border-radius:8px 8px 0 0}.si-editor .si-extra[open] .si-extra-caret{transform:rotate(180deg)}.si-editor .si-extra>:not(summary){margin-inline:18px}.si-editor .si-extra>.si-section:first-of-type{margin-top:18px}.si-editor .si-extra>.si-line:last-child{margin-bottom:22px}
